func generateParenthesis(n int) []string {
    var res []string
    var path []byte
    var backtrack func(int, int)
    backtrack = func(open, close int) {
        if len(path) == 2*n {
            res = append(res, string(path))
            return
        }
        if open < n {
            path = append(path, '(')
            backtrack(open+1, close)
            path = path[:len(path)-1]
        }
        if close < open {
            path = append(path, ')')
            backtrack(open, close+1)
            path = path[:len(path)-1]
        }
    }
    backtrack(0, 0)
    return res
}
